def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    denominator = 1 + (v2 / 100.0)

    if denominator == 0:
        return None

    result = v1 / denominator

    return {
        "value": round(result, 3),
        "trace": {
            "net_revenues_2017": v1,
            "change_rate_percent": v2,
            "change_factor": denominator,
            "net_revenues_2016": round(result, 3),
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": "currency"
            }
        }
    }
